import{_ as e,o,c as s,a2 as a}from"./chunks/framework.CqdVOxXJ.js";const r="/rakkii-cars-guide/screenshots/v2/b01-my-jobs.png",n="/rakkii-cars-guide/screenshots/v2/b03-tech-job.png",i="/rakkii-cars-guide/screenshots/v2/b04-tech-checklist.png",h="/rakkii-cars-guide/screenshots/v2/b05-qc-photos.png",y=JSON.parse('{"title":"Your day in the bay","description":"","frontmatter":{},"headers":[],"relativePath":"technician/index.md","filePath":"technician/index.md","lastUpdated":1794643263000}'),l={name:"technician/index.md"};function c(p,t,d,g,u,k){return o(),s("div",null,[...t[0]||(t[0]=[a(`<h1 id="your-day-in-the-bay" tabindex="-1">Your day in the bay <a class="header-anchor" href="#your-day-in-the-bay" aria-label="Permalink to &quot;Your day in the bay&quot;">​</a></h1><p><strong>For:</strong> Technicians · <strong>You use:</strong> Workshop › My jobs, and the Me hub</p><p>Your day in six steps. Each step is short; the details under it are only for when you need them.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1 Clock in → 2 Open your job → 3 Tick the checklist → 4 Send to QC</span></span>
<span class="line"><span>→ 5 Take the 4 QC photos → 6 Clock out</span></span></code></pre></div><h2 id="_1-clock-in" tabindex="-1">1. Clock in <a class="header-anchor" href="#_1-clock-in" aria-label="Permalink to &quot;1. Clock in&quot;">​</a></h2><ol><li>Open the app. You land on <strong>My jobs</strong>.</li><li>Press <strong>Clock in</strong> at the top. (You can also use <strong>Me › Time clock</strong>.)</li><li>If the shop asks for a photo, take it.</li></ol><p><img src="`+r+'" alt="My jobs on a phone: Clock in, Assigned to me (empty here) and Other cars on the floor"></p><div class="tip custom-block"><p class="custom-block-title">Away from the shop?</p><p>On a road test or a parts run, the app warns that you&#39;re outside the shop area. Type a reason (for example &quot;Road test on Roosevelt Ave&quot;) and clock in anyway. The owner approves it later.</p></div><p>Shop tablet: if the owner runs the <strong>Clock kiosk</strong>, just tap your name on the tablet.</p><h2 id="_2-open-your-job" tabindex="-1">2. Open your job <a class="header-anchor" href="#_2-open-your-job" aria-label="Permalink to &quot;2. Open your job&quot;">​</a></h2><p><strong>My jobs</strong> shows:</p><ul><li><strong>Assigned to me</strong>: your jobs. Tap a plate to open it.</li><li><strong>Done, waiting for pickup</strong>: cars you finished.</li><li><strong>Other cars on the floor</strong>: other technicians&#39; jobs. You can look but not change them.</li></ul><p>The job opens on the <strong>Work</strong> tab. Read the work lines and <strong>Notes</strong>: they tell you what to do. Prices are hidden from technicians.</p><p>The top of the job tells you what to do next, for example &quot;Finish the bay checklist (2 steps left), then send to QC.&quot;</p><p><img src="'+n+'" alt="A job on a technician&#39;s phone: status, next step and the Work tab"></p><div class="info custom-block"><p class="custom-block-title">&quot;View only: you are not assigned to this job.&quot;</p><p>You opened someone else&#39;s job. Ask the desk to assign you if you need to work on it.</p></div><h2 id="_3-tick-the-bay-checklist" tabindex="-1">3. Tick the bay checklist <a class="header-anchor" href="#_3-tick-the-bay-checklist" aria-label="Permalink to &quot;3. Tick the bay checklist&quot;">​</a></h2><ol><li>On the <strong>Work</strong> tab, find <strong>Bay checklist</strong>.</li><li>Tick each step <strong>when it&#39;s really done</strong>. The app saves your name and the time.</li><li>Missing a step? Type it in <strong>New step</strong> and press <strong>Add step</strong>.</li><li>Add progress photos with <strong>Other photo</strong> if useful.</li></ol><p><img src="'+i+'" alt="Bay checklist with ticked steps"></p><h2 id="_4-send-the-car-to-qc" tabindex="-1">4. Send the car to QC <a class="header-anchor" href="#_4-send-the-car-to-qc" aria-label="Permalink to &quot;4. Send the car to QC&quot;">​</a></h2><p>When the work is done, press <strong>Send to QC</strong> at the bottom of the <strong>Bay checklist</strong> card.</p><ul><li>If checklist steps are still open, the app asks first. Go back and tick them, or press <strong>Send to QC anyway</strong> if they really don&#39;t apply.</li><li>The status changes to <strong>Quality check</strong>.</li></ul><p><strong>Stuck while working?</strong> Use these instead:</p><table tabindex="0"><thead><tr><th>Button</th><th>Use it when</th></tr></thead><tbody><tr><td><strong>Waiting for parts</strong></td><td>You&#39;re waiting for an ordered part. Press <strong>Parts in — back to shop</strong> when it arrives.</td></tr><tr><td><strong>Put on hold</strong> (in <strong>More ▾</strong>)</td><td>Work must stop for another reason. Type why. The desk or you press <strong>Resume</strong> later.</td></tr></tbody></table><h2 id="_5-take-the-four-qc-photos" tabindex="-1">5. Take the four QC photos <a class="header-anchor" href="#_5-take-the-four-qc-photos" aria-label="Permalink to &quot;5. Take the four QC photos&quot;">​</a></h2><p>The car can&#39;t be marked <strong>Ready for pickup</strong> until it has four photos:</p><p><strong>Front</strong> · <strong>Rear</strong> · <strong>Left side (LS)</strong> · <strong>Right side (RS)</strong></p><ol><li>On the <strong>Work</strong> tab, find <strong>QC photos</strong>.</li><li>On each angle, press <strong>Take photo</strong> (or <strong>Choose file</strong> for a photo you already took).</li><li>Each finished angle gets a ✓ and its buttons disappear. The counter goes from <strong>0/4</strong> to <strong>4/4</strong>.</li><li>Wrong photo? Use <strong>Replace a photo</strong>.</li></ol><p><img src="'+h+'" alt="QC photos card on a phone, before any photos: four angles, each with Choose file and Take photo"></p><p>That&#39;s your part done. The desk marks the car <strong>Ready for pickup</strong> and releases it.</p><h2 id="_6-before-you-go-home" tabindex="-1">6. Before you go home <a class="header-anchor" href="#_6-before-you-go-home" aria-label="Permalink to &quot;6. Before you go home&quot;">​</a></h2><ul><li>[ ] Checklist ticked for today&#39;s work</li><li>[ ] Waiting cars set to <strong>Waiting for parts</strong>, blocked cars <strong>On hold</strong> with a reason</li><li>[ ] QC photos on every car you finished</li><li>[ ] Insurance jobs: replaced parts logged in <strong>Surrendered Parts</strong> (see below)</li><li>[ ] <strong>Clock out</strong></li></ul><h2 id="sometimes" tabindex="-1">Sometimes <a class="header-anchor" href="#sometimes" aria-label="Permalink to &quot;Sometimes&quot;">​</a></h2><h3 id="insurance-jobs-surrendered-parts" tabindex="-1">Insurance jobs: surrendered parts <a class="header-anchor" href="#insurance-jobs-surrendered-parts" aria-label="Permalink to &quot;Insurance jobs: surrendered parts&quot;">​</a></h3><p>Insurers often want the damaged parts back. On insurance jobs the <strong>Work</strong> tab has a <strong>Surrendered Parts</strong> card.</p><ol><li>Press <strong>Add part</strong>.</li><li>Fill in the part, <strong>Qty</strong>, <strong>Surrender date</strong> and who received it, then save.</li><li>If nothing goes back to the insurer, tick <strong>No parts to surrender</strong>.</li></ol><h3 id="canvass-and-parts-buying" tabindex="-1">Canvass and parts buying <a class="header-anchor" href="#canvass-and-parts-buying" aria-label="Permalink to &quot;Canvass and parts buying&quot;">​</a></h3><p>Some technicians are allowed to get supplier prices or buy parts. If you are, the job shows a <strong>Canvass</strong> tab. See <a href="/rakkii-cars-guide/reference/09-parts-inventory-canvass-restock-payables">Parts, canvass &amp; payables</a>.</p><h3 id="forms-and-calendar" tabindex="-1">Forms and calendar <a class="header-anchor" href="#forms-and-calendar" aria-label="Permalink to &quot;Forms and calendar&quot;">​</a></h3><ul><li><strong>Workshop › Calendar</strong>: which cars are due on which day.</li><li><strong>Workshop › Forms</strong>: the intake checklist and the pick-up &amp; delivery waiver.</li></ul><h3 id="leave-overtime-and-payslips" tabindex="-1">Leave, overtime and payslips <a class="header-anchor" href="#leave-overtime-and-payslips" aria-label="Permalink to &quot;Leave, overtime and payslips&quot;">​</a></h3><p>All in the <strong>Me</strong> hub. See <a href="/rakkii-cars-guide/me/">Me hub</a>.</p>',42)])])}const m=e(l,[["render",c]]);export{y as __pageData,m as default};
